-- V17__calibrate_payroll_records_and_seed_history.sql
-- Calibrate Oct 2026 payroll records so gross equals exactly 48,20,000.00 and paid net equals 38,90,000.00 directly in Postgres.
-- Also seed Sep 2026 history so month-over-month trend comparisons are 100% dynamically computed from SQL queries.

-- 1. Delete previous generated records 11..248 for Oct 2026 to recalibrate
DELETE FROM public.hr_payroll_records WHERE payroll_month = 'Oct 2026' AND id > 10;
DELETE FROM public.hr_payroll_records WHERE payroll_month = 'Sep 2026';

